const AfricasTalking = require('africastalking');

class AfricasTalkingService {
  constructor(credentials) {
    this.client = AfricasTalking({
      apiKey: credentials.apiKey,
      username: credentials.username
    });
    this.sms = this.client.SMS;
    this.voice = this.client.VOICE || this.client.voice || null;
  }

  async sendSMS(phoneNumber, message, shortCode = null) {
    try {
      const options = {
        to: [phoneNumber],
        message: message,
        from: shortCode || ''
      };

      const response = await this.sms.send(options);
      const result = response.SMSMessageData.Recipients[0];

      // todo: Check if returning an error in case of a api failure is better and implement it.
      return {
        success: result.status === 'Success',
        linkId: result.linkId,
        id: result.messageId,
        statusCode: result.statusCode,
        status: result.status,
        cost: result.messageCost,
        error: result.status !== 'Success' ? result.status : null
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  async sendIVR(phoneNumber, options = {}) {
    try {
      if (!this.voice || typeof this.voice.call !== 'function') {
        return {
          success: false,
          error: 'Africa\'s Talking voice client is unavailable'
        };
      }

      const callOptions = {
        phoneNumber,
        callerId: options.callerId || null,
        ...(options.audioUrl ? { mediaUrl: options.audioUrl } : {})
      };

      const response = await this.voice.call(callOptions);
      const payload = response?.data || response || {};

      return {
        success: payload.status === 'Ok' || payload.status === 'Success' || !!payload.sessionId,
        sessionId: payload.sessionId || payload.session_id || null,
        status: payload.status || 'Unknown',
        error: payload.status && payload.status !== 'Ok' && payload.status !== 'Success' ? payload.errorMessage || payload.error : null
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  async playText(sessionId, ttsText) {
    try {
      const response = await this.voice.playText({ sessionId, text: ttsText });

      return {
        success: true,
        status: response.status
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }
}

module.exports = AfricasTalkingService;